    55	const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
    56	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
    57	  clients.push(client);
    58	  const frames: Frame[] = [];
    59	  let connected: Frame = {type: ''};
    60	  await new Promise<void>(resolve => {
    61	    client.on('message', raw => {
    62	      const frame = JSON.parse(String(raw)) as Frame;
    63	      if (frame.type === 'pong') {
    64	        resolve();
    65	        return;
    66	      }
    67	      if (frame.type !== 'connected') {
    68	        frames.push(frame);
    69	        return;
    70	      }
    71	      connected = frame;
    72	      client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
    73	      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
    74	    });
    75	  });
    76	  return {connected, frames};
    77	};
